buggyCode:
def count_vowels(s):
    vowels = "aeiou"
    return sum(1 for ch in s if ch in vowels)

solutionCode:
def count_vowels(s):
    vowels = "aeiouAEIOU"
    return sum(1 for ch in s if ch in vowels)

testHarness:
from solution import count_vowels

cases = [
    ("hello", 2),
    ("HELLO", 2),
    ("AeIoU", 5),
    ("xyz", 0),
    ("", 0),
]

for inp, expected in cases:
    label = repr(inp)
    try:
        actual = count_vowels(inp)
        if actual == expected:
            print(f"PASS\t{label}")
        else:
            print(f"FAIL\t{label}\t{expected}\t{actual}")
    except Exception as e:
        print(f"ERROR\t{label}\t{type(e).__name__}: {e}")
